WITH enriched AS (SELECT s.*, o.amount AS order_amount, o.discount FROM payments s INNER JOIN orders o ON s.order_id = o.id) SELECT s.id, s.order_id, s.method, s.amount, s.paid_at, s.order_amount, CASE WHEN method RLIKE '^(promptpay|card)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS method_zone, (SELECT SUM(p2.amount) FROM payments p2 WHERE p2.order_id = s.order_id) AS sum_payment_amount FROM enriched s ORDER BY paid_at NULLS FIRST, method DESC;
